class Solution {
public:
    int myAtoi(const string &s) {
        int n = s.size();
        int i = 0;

        while (i < n && s[i] == ' ') {
            ++i;
        }

        int sign = 1;


        if (i < n && (s[i] == '-' || s[i] == '+')) {
            sign = s[i] == '-' ? -1 : 1;
            ++i;
        }

        int result = 0;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            int digit = s[i] - '0';

            if (result > (INT_MAX - digit) / 10) {
                return sign == -1 ? INT_MIN : INT_MAX;
            }

            result = result * 10 + digit;
            ++i;
        }

        return result * sign;
    }
};

