#pragma GCC optimize("Ofast")

#include <iostream>
#include <string>

static constexpr std::size_t max_align = alignof(std::max_align_t);
alignas(max_align) static unsigned char BUFFER[64 * 1024 * 1024];
static std::size_t pos = 0;

void *operator new(const std::size_t size) {
    const std::size_t padding = (max_align - (pos % max_align)) % max_align;
    pos += padding + size;
    return static_cast<void *>(&BUFFER[pos - size]);
}

void *operator new[](const std::size_t size) {
    return operator new(size);
}

void operator delete(void *) noexcept {}

void operator delete[](void *) noexcept {}

void operator delete(void *, std::size_t) noexcept {}

void operator delete[](void *, std::size_t) noexcept {}

class Solution {
public:
    Solution() {
        std::ios::sync_with_stdio(false);
        std::cout.tie(nullptr);
        std::cin.tie(nullptr);
    }

    int numDecodings(const std::string& s) {
        if (s[0] == '0') return 0;
        if (s.length() == 1) return 1;

        unsigned int dp[s.length()];
        dp[0] = 1;

        for (std::uint8_t i = 1; i < s.length(); ++i) {
            char prev = s[i - 1], curr = s[i];
            if (curr == '0' && (prev == '0' || prev > '2')) return 0;

            if (prev == '0') dp[i] = dp[i - 1];
            else {
                if (curr == '0') dp[i] = dp[i - 1];

                else {
                    dp[i] = dp[i - 1];
                    if (i == s.length() - 1 || s[i + 1] != '0') {
                        std::uint8_t num = (prev - '0') * 10 + (curr - '0');

                        if (num <= 26) {
                            if (i > 1) dp[i] += dp[i - 2];
                            else dp[i] += 1;
                        }
                    }
                }
            }
        }

        return static_cast<int>(dp[s.length() - 1]);
    }
};

