class Solution {
public:
    int numDistinct(string s, string t) {
        if (s.size() < t.size()) return 0;
        if (s.size() == t.size()) return s == t;
        vector<int64_t> dp0(s.size()), dp1(s.size());
        for (int i = 0; i <= s.size() - t.size(); ++i) dp0[i] = s[i] == t[0];
        int64_t sum;
        for (int i = 1; i < t.size(); ++i) {
            sum = dp0[i - 1];
            for (int j = i; j <= s.size() - t.size() + i; ++j) {
                if (s[j] == t[i]) dp1[j] = sum;
                sum += dp0[j];
            }
            swap(dp0, dp1);
            for (int j = i; j <= s.size() - t.size() + i; ++j) dp1[j] = 0;
        }
        return accumulate(dp0.begin() + t.size() - 1, dp0.end(), 0);
    }
};

