typedef struct {
    size_t advance;
    string_view sv;
} expected_sv;
class Solution {
    using str_result = optional<expected_sv>;
    using result = optional<size_t>; // advance
    const size_t npos = string_view::npos;

    static bool isUpperAlpha(char c) { return c >= 'A' && c <= 'Z'; }
    str_result parseOpenTag(string_view sv) {
        // cout << "parsing open " << sv << "\n";
        if (!sv.starts_with("<"))
            return nullopt;
        size_t end = sv.find('>');
        if (end == npos)
            return nullopt;
        if (end - 1 < 1 || end - 1 > 9)
            return nullopt;
        auto res = sv.substr(1, end-1);
        if (!all_of(res.begin(), res.end(), isUpperAlpha))
            return nullopt;
        return expected_sv{end + 1, res};
    }
    result parseCloseTag(string_view sv, string_view open_tag) {
                // cout << "parsing close " << sv << "\n";

        if (!sv.starts_with("</"))
            return nullopt;
        size_t end = sv.find('>');
        if (end == npos)
            return nullopt;
        auto res = sv.substr(2, end-2);
        if (res != open_tag)
            return nullopt;
        return end + 1;
    }
    result parse_cdata(string_view sv) {
                // cout << "parsing cdata " << sv << "\n";

        if (!sv.starts_with("<![CDATA["))
            return nullopt;
        // size_t nstart = string("<![CDATA[").size();
        size_t end = sv.find("]]>");
        if (end == npos)
            return nullopt;
        return end + 3;
    }
    result parse_tag(string_view sv) {
                // cout << "parsing tag " << sv << "\n";

        size_t cursor = 0;
        if (sv.size() == 0)
            return nullopt;
        if (sv[cursor] != '<')
            return nullopt;
        auto open = parseOpenTag(sv.substr(cursor));
        if (!open.has_value())
            return nullopt;
        cursor += open.value().advance;
        while (cursor < sv.size()) {
            while (cursor < sv.size() && sv[cursor] != '<') {
                cursor += 1;
            }
            if (cursor == sv.size())
                return cursor;
            // try close tag
            auto close = parseCloseTag(sv.substr(cursor), open.value().sv);
            if (close.has_value()) {
                cursor += close.value();
                return cursor;
            }
            // try tag
            auto tag = parse_tag(sv.substr(cursor));
            if (tag.has_value()) {
                cursor += tag.value();
                continue;
            }
            // try cdata
            tag = parse_cdata(sv.substr(cursor));
            if (tag.has_value()) {
                cursor += tag.value();
                continue;
            }
            return nullopt;
        }
        return nullopt;
    }

public:
    bool isValid(string code) {
        auto res = parse_tag(code);
        if (!res.has_value())
            return false;
        if (res.value() != code.size())
            return false;
        return true;
    }
};

