class Solution {
public:
    vector<int> singleNumber(vector<int>& nums) {
        long long xorAll = 0;
        for(const int& e : nums) {
            xorAll = xorAll ^ e;
        }
        long long diff = xorAll & (-xorAll);
        int x = 0;
        int y = 0;
        for(const int& e : nums) {
            if((e&diff) != 0) {
                x = x^e;
            } else {
                y = y^e;
            }
        }
        return {x, y};
    }
};

