class Solution {
public:
    int getSum(int a, int b) {
        int x = 0;
        int c = 0;
        for (int i = 0; i < 32; ++i) {
            int v = c;
            if (a & (1 << i)) {
                v++;
            }
            if (b & (1 << i)) {
                v++;
            }
            c = 0;
            if (v == 2) {
                v = 0;
                c = 1;
            }else if (v == 3) {
                v = 1;
                c = 1;
            }
            if (v) {
                x |= (1 << i);
            }
        }
        return x;
    }
};

