class Solution {
public:
    int pathSum(TreeNode* root,int &sum){
        if(root==NULL)return 0;
        int ls=max(0,pathSum(root->left,sum));
        int rs=max(0,pathSum(root->right,sum));
        sum=max(ls-rs+root->val,sum);
        return max(ls,rs)+root->val;
