class Solution {
public:
    vector<int> countSmaller(vector<int>& nums) {
        BinaryIndexedTree tree{};
        vector<int> ans(nums.size());
        for (auto i{nums.size() - 1}; ~i; --i) {
            const auto num{nums[i]};
            ans[i] = tree.Query(num);
            tree.Update(num);
        }

        return ans;
    }

private:
    class BinaryIndexedTree {
    public:

        BinaryIndexedTree() { }

        void Update(int val) {
            auto i{val + 10001};
            while (i < n_) {
                ++data_[i];
                i += i & -i;
            }
        }

        int Query(int val) {
            int result{0};
            auto i{val + 10000};
            while (i > 0) {
                result += data_[i];
                i -= i & -i;
            }
            return result;
        }

    private:
        static constexpr size_t n_{20001};
        array<int, n_> data_{};
    };
};

