using ll = long long;
int upper, lower;
const int MAXN = 1e5 + 1;

ll s[MAXN];
ll aux[MAXN];
int dnc(int l, int r)
{
    if (l == r) return 0;

    int m = (l + r) / 2;
    int ans = dnc(l, m) + dnc(m+1, r);

    int wl = l, wr = l;
    for (int i = m+1; i <= r; ++i)
    {
        ll a = s[i] - upper;
        ll b = s[i] - lower;
        while (wl <= m and s[wl] < a) wl++;
        while (wr <= m and s[wr] <= b) wr++;
        ans += wr - wl;
    }

    int i = l, j = m+1, k = 0;
    while (i <= m and j <= r)
        if (s[i] <= s[j])
            aux[k++] = s[i++];
        else
            aux[k++] = s[j++];
    while (i <= m) aux[k++] = s[i++];
    while (j <= r) aux[k++] = s[j++];
    for (int i = l, k = 0; i <= r; ++i, ++k) s[i] = aux[k];

    return ans;
}


class Solution {
public:
    int countRangeSum(vector<int>& nums, int lo, int up) {
        lower = lo; upper = up;
        s[0] = 0;
        for (int i = 1; i <= nums.size(); ++i)
            s[i] = s[i - 1] + nums[i - 1];
        return dnc(0, nums.size());
    }
};

