class Solution {
public:
    int helper(vector<int>& nums, int low, int high) {
        if (low >= high) {
            return 0;
        }
        int mid = low + (high - low) / 2;
        int leftCount = helper(nums, low, mid);
        int rightCount = helper(nums, mid + 1, high);

        int left = low;
        int right = mid + 1;
        int currCount = 0;
        while (left <= mid) {
            while (right <= high && (long)nums[left] > (long)2 * nums[right]) {
                right++;
            }
            currCount += right - (mid + 1);
            left++;
        }
        sort(nums.begin() + low, nums.begin() + high + 1);
        return leftCount + currCount + rightCount;
    }
    int reversePairs(vector<int>& nums) {
        int ans = helper(nums, 0, nums.size() - 1);
        return ans;
    }
};

