#include <vector>

using namespace std;

class Solution {
public:
    int head[2005];
    int to[5005];
    int nxt[5005];
    int degree[2005];
    int q[2005];
    int edge_cnt;

    int add_edge(int u, int v) {
        to[edge_cnt] = v;
        nxt[edge_cnt] = head[u];
        head[u] = edge_cnt++;
        return 0;
    }

    bool canFinish(int n, vector<vector<int>>& pre) {
        edge_cnt = 0;
        for (int i = 0; i < n; i++) {
            head[i] = -1;
            degree[i] = 0;
        }

        for (auto& p : pre) {
            add_edge(p[1], p[0]);
            degree[p[0]]++;
        }

        int h = 0, t = 0;
        for (int i = 0; i < n; i++) {
            if (degree[i] == 0) {
                q[t++] = i;
            }
        }

        int visited_count = 0;
        while (h < t) {
            int curr = q[h++];
            visited_count++;

            for (int i = head[curr]; i != -1; i = nxt[i]) {
                int neighbor = to[i];

                if (--degree[neighbor] == 0) {
                    q[t++] = neighbor;
                }
            }
        }

        return visited_count == n;
    }
};

