const int N = 605;
const int A = 26;
const int M = A * A * A;

vector <int> g_from[N];
string id_to_string[N];
int itin[N];
int n, k;

class Solution {
public:
    void findLeastPath(int v)
    {
        for (int u; !g_from[v].empty(); u = -g_from[v].back(), g_from[v].pop_back(), v = u) itin[k++] = v;
        itin[k++] = v;
    }

    void solve(int start)
    {
        //cout << id_to_string[start] << "\n";
        int k0 = k;
        findLeastPath(start);
        //for (int i = k0; i < k; ++i) cout << id_to_string[itin[i]] << " ";
        //cout << "\n";
        for (int i = k - 1; i >= k0; --i)
        {
            if (g_from[itin[i]].empty()) continue;
            int k1 = k;
            solve(itin[i]);
            --k;
            rotate(itin + i, itin + k1, itin + k);
        }
    }

    vector<string> findItinerary(vector<vector<string>>& tickets) {
        int m = tickets.size(); n = 0;
        for (int i = 0; i < m; ++i)
        {
            id_to_string[n++] = tickets[i][0];
            id_to_string[n++] = tickets[i][1];
        }
        sort(id_to_string, id_to_string + (m<<1));
        n = 0;
        for (int i = 0; i < (m<<1); ++i)
        {
            if (i == 0 || id_to_string[i] != id_to_string[i-1]) id_to_string[n++] = id_to_string[i];
        }
        for (int i = 0; i < n; ++i)
        {
            g_from[i].clear();
        }
        for (const vector <string>& edge: tickets)
        {
            //int i0 = lower_bound(id_to_string, id_to_string + n, edge[0]), i1 = lower_bound(id_to_string, id_to_string + n, edge[1]);
            int i0, i1;
            for (i0 = 0; i0 < n && id_to_string[i0] != edge[0]; ++i0);
            for (i1 = 0; i1 < n && id_to_string[i1] != edge[1]; ++i1);
            g_from[i0].push_back(-i1);
        }

        for (int i = 0; i < n; ++i)
        {
            sort(g_from[i].begin(), g_from[i].end());
        }

        int start;
        for (start = 0; id_to_string[start] != "JFK"; ++start);

        k = 0;
        solve(start);

        vector <string> ans(k);
        for (int i = 0; i < k; ++i) ans[i] = id_to_string[itin[i]];

        return ans;
    }
};

