class UnionFind {
  public:
  UnionFind(int n) : count(n), id(n) {
  iota(begin(id), end(id), 0);
  }

  void union_(int u, int v) {
  const int i = find(u);
  const int j = find(v);
  if (i == j)
  return;
  id[i] = j;
  --count;
  }

  int getCount() const {
  return count;
  }

  private:
  int count;
  vector<int> id;

  int find(int u) {
  return id[u] == u ? u : id[u] = find(id[u]);
  }
 };

 class Solution {
  public:
  int minSwapsCouples(vector<int>& row) {
  const int n = row.size() / 2;
  UnionFind uf(n);

  for (int i = 0; i < n; ++i) {
  const int a = row[2 * i];
  const int b = row[2 * i + 1];
  uf.union_(a / 2, b / 2);
  }

  return n - uf.getCount();
  }
 };

