class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        int n = graph.size();
        if (n <= 1) return 0;

        int target = (1 << n) - 1;
        int vis[4096] = {0}; 
        int q[49152];
        int head = 0, tail = 0;

        for (int i = 0; i < n; i++) {
            q[tail++] = (i << 12) | (1 << i);
            vis[1 << i] |= (1 << i);
        }

        int dist = 0;
        while (head < tail) {
            int size = tail - head;

            while (size--) {
                int state = q[head++];
                int u = state >> 12;
                int mask = state & 4095;
                for (int v : graph[u]) {
                    int next_mask = mask | (1 << v);
                    if (next_mask == target) return dist + 1;
                    if ((vis[next_mask] & (1 << v)) == 0) {
                        vis[next_mask] |= (1 << v);
                        q[tail++] = (v << 12) | next_mask;
                    }
                }
            }
            dist++; 
        }

        return 0;
    }
};

